import csv, json, math, statistics
from datetime import date

bands=['VH','VV','VV-VH']
# load pivot
hist=[]
by_period={}
for r in csv.DictReader(open('data.csv')):
    by_period.setdefault(r['period_id'], {'date':date.fromisoformat(r['date'])})[r['band']]=float(r['y'])
hist=sorted(by_period.values(), key=lambda x:x['date'])

# helper: interpolate within a calendar year by day-of-year for a band
by_year={}
for row in hist:
    by_year.setdefault(row['date'].year, []).append(row)
for y in by_year:
    by_year[y].sort(key=lambda r:r['date'])

def doy(dt):
    return dt.timetuple().tm_yday

def interp_year(year, target_doy, band):
    rows=by_year.get(year, [])
    pts=[(doy(r['date']), r[band]) for r in rows if band in r]
    if not pts: return None
    pts.sort()
    # exact / bracketing
    if target_doy <= pts[0][0]:
        # use nearest at boundary
        return pts[0][1]
    if target_doy >= pts[-1][0]:
        return pts[-1][1]
    for (d1,v1),(d2,v2) in zip(pts, pts[1:]):
        if d1 <= target_doy <= d2:
            if d2==d1: return v1
            a=(target_doy-d1)/(d2-d1)
            return v1*(1-a)+v2*a
    return min(pts, key=lambda p:abs(p[0]-target_doy))[1]

# estimate annual same-season drift from 2023 to 2024 where both exist, per band
trend={}
for b in bands:
    diffs=[]
    # compare 2024 observed dates to 2023 same doy interpolation
    for r in by_year.get(2024, []):
        base=interp_year(2023, doy(r['date']), b)
        if base is not None:
            diffs.append(r[b]-base)
    trend[b]=statistics.median(diffs) if diffs else 0.0
print('trend', trend)

# To avoid over-extrapolating noisy drift, shrink trend toward zero
trend={b:0.5*trend[b] for b in bands}

pred={}
for v in csv.DictReader(open('visits_to_predict.csv')):
    dt=date.fromisoformat(v['date'])
    td=doy(dt)
    # primary analog: same season one year earlier if available; otherwise latest complete prior analogous year
    out={}
    for b in bands:
        base=interp_year(dt.year-1, td, b)
        years_ahead=1
        if base is None:
            base=interp_year(2023, td, b)
            years_ahead=dt.year-2023
        # for 2025 Jan-Aug use 2024 analog where available (Jan-Mar, Jul-Aug), else 2023 analog plus drift
        if dt.year==2025:
            b2024=interp_year(2024, td, b)
            if b2024 is not None:
                base=b2024; years_ahead=1
            else:
                base=interp_year(2023, td, b); years_ahead=2
        out[b]=round(float(base + years_ahead*trend[b]), 6)
    pred[v['period_id']]=out

rationale=("Predicted each requested visit from the parcel's own past visits using a recursive seasonal-historical-control analogue: "
           "for each target date and band, the value was interpolated from the same day-of-year in prior observed years and adjusted by a "
           "shrunk median year-over-year drift estimated from overlapping 2023-2024 history. This preserves the parcel's observed seasonal "
           "SAR band pattern while avoiding use of external controls; bands predicted were VH, VV, and VV-VH for all requested period_ids.")
answer={'prediction':pred,'rationale':rationale}
json.dump(answer, open('answer.json','w'), indent=2)
print(json.dumps({'periods':len(pred),'first':next(iter(pred.items())),'last':list(pred.items())[-1]}, indent=2))
