python3 - <<'PY'
import csv, json, subprocess, sys, shutil
from pathlib import Path
current=Path('iter_data.csv'); shutil.copyfile('data.csv', current)
visits=list(csv.DictReader(open('visits_to_predict.csv')))
bands=[]
for r in csv.DictReader(open('data.csv')):
    if r['band'] not in bands: bands.append(r['band'])
pred_by_period={}
mses=[]
for v in visits:
    res=subprocess.run([sys.executable,'scripts/run_shc_band_forecast.py','--input',str(current),
                        '--out','iter_answer.json','--summary-out','iter_summary.json',
