import csv, json, math, datetime, statistics
from pathlib import Path

def date_to_ord(s):
    return datetime.date.fromisoformat(s).toordinal()

# small Gaussian elimination solver for normal equations
def solve_linear(A, b):
    n=len(b)
    M=[row[:] + [b[i]] for i,row in enumerate(A)]
    for col in range(n):
        piv=max(range(col,n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) < 1e-12:
            M[col][col] += 1e-8
            piv=col
        M[col],M[piv]=M[piv],M[col]
        div=M[col][col]
        if abs(div)<1e-15: div=1e-15
        for j in range(col,n+1): M[col][j]/=div
        for r in range(n):
            if r==col: continue
            fac=M[r][col]
            if fac:
                for j in range(col,n+1):
                    M[r][j]-=fac*M[col][j]
    return [M[i][n] for i in range(n)]

def features(day, t_index, t0):
    # annual cycle using actual day, plus linear/weak quadratic trend over visit index
    x=(day-t0)/365.2425
    return [
        1.0,
        t_index,
        t_index*t_index/10000.0,
        math.sin(2*math.pi*x), math.cos(2*math.pi*x),
        math.sin(4*math.pi*x), math.cos(4*math.pi*x),
        math.sin(6*math.pi*x), math.cos(6*math.pi*x),
    ]

rows=list(csv.DictReader(open('data.csv')))
visits=list(csv.DictReader(open('visits_to_predict.csv')))
bands=sorted({r['band'] for r in rows})
# period index mapping, including future sequentially
periods=[]
seen=set()
for r in rows:
    if r['period_id'] not in seen:
        seen.add(r['period_id']); periods.append((r['period_id'], r['date']))
for v in visits:
    if v['period_id'] not in seen:
        seen.add(v['period_id']); periods.append((v['period_id'], v['date']))
pidx={p:i for i,(p,d) in enumerate(periods)}
t0=min(date_to_ord(r['date']) for r in rows)

byband={b:[] for b in bands}
for r in rows:
    byband[r['band']].append((pidx[r['period_id']], date_to_ord(r['date']), float(r['y'])))

coefs={}
rmse={}
for b, obs in byband.items():
    # ridge regression
    X=[features(day, idx, t0) for idx,day,y in obs]
    y=[v for idx,day,v in obs]
    p=len(X[0])
    A=[[0.0]*p for _ in range(p)]
    B=[0.0]*p
    for xi,yi in zip(X,y):
        for i in range(p):
            B[i]+=xi[i]*yi
            for j in range(p):
                A[i][j]+=xi[i]*xi[j]
    # tiny ridge; don't penalize intercept much
    for i in range(p):
        A[i][i]+= 1e-6 if i==0 else 1e-3
    beta=solve_linear(A,B)
    coefs[b]=beta
    pred=[sum(beta[i]*xi[i] for i in range(p)) for xi in X]
    rmse[b]=math.sqrt(sum((a-bb)**2 for a,bb in zip(y,pred))/len(y))

