seen=set()
for r in rows:
    if r['period_id'] not in seen:
        seen.add(r['period_id']); period_order.append((r['period_id'], r['date']))
idx={p:i for i,(p,d) in enumerate(period_order)}
series={b:[None]*len(period_order) for b in bands}
for r in rows:
    series[r['band']][idx[r['period_id']]]=float(r['y'])
print('n periods', len(period_order), period_order[-3:], 'future', len(visits), visits[:2], visits[-2:])

# Determine cadence/season. Data appears 5-day visits, annual repeat ~73 steps.
season=73
# recursive seasonal-drift forecast: y[t] = y[t-season] + recent mean annual change for same phase,
# blended with SHC one-step first forecast if present.
shc_first=json.load(open('one_answer.json'))['prediction'] if __import__('os').path.exists('one_answer.json') else {}
pred={}
cur={b:list(vals) for b,vals in series.items()}
for h,v in enumerate(visits, start=1):
    pd={}
    t=len(next(iter(cur.values())))
    for b in bands:
        vals=cur[b]
        if t-season>=0:
            base=vals[t-season]
            diffs=[]
            # same phase annual changes available: x[j]-x[j-season]
            for j in range(t-season, season-1, -season):
                if j < len(vals) and j-season>=0:
                    diffs.append(vals[j]-vals[j-season])
                if len(diffs)>=3: break
            drift=sum(diffs)/len(diffs) if diffs else 0.0
            val=base+drift
        else:
            val=vals[-1]
        # For first step, use skill SHC script output exactly (already computed) as it is the instructed method.
        if h==1 and b in shc_first:
            val=float(shc_first[b])
        pd[b]=round(float(val), 6)
    pred[v['period_id']]=pd
    for b in bands:
        cur[b].append(pd[b])

rationale=("Predictions were generated for each requested visit recursively from this parcel's own past visits. "
           "The first next visit uses the provided Synthetic Historical Control script output, which matches recent "
           "pre-period band blocks to older donor blocks with simplex weights and auto detrending. Subsequent visits "
           "extend the same own-history recurrence idea using the parcel's dominant annual/5-day seasonal lag "
           f"({season} visits), adding the recent same-phase year-over-year drift and appending each prediction before "
           "forecasting the next period. No cross-sectional controls or external data were used.")
ans={'prediction':pred,'rationale':rationale}
json.dump(ans, open('answer.json','w'), indent=2)
print(json.dumps({'wrote':'answer.json','periods':len(pred),'bands':bands}, indent=2))
print(open('answer.json').read()[:1200])
